import { API_BASE_URL } from '../config/api';

export interface OnboardingChoices {
  notify: boolean;
  theme: 'dark' | 'light';
  languages: string[];
}

export async function completeOnboarding(choices: OnboardingChoices): Promise<{ done: true }> {
  const response = await fetch(`${API_BASE_URL}/onboarding`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(choices),
  });
  if (!response.ok) throw new Error(`Onboarding failed with status ${response.status}`);
  return { done: true };
}

import { useCallback, useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { completeOnboarding } from '../services/onboarding';

const colors = {
  bg: '#0f120e',
  success: '#4ade80',
  border: '#242a24',
  accent: '#f05039',
  text: '#f5f5f0',
  textMuted: '#a8ada6',
  surface: '#1a1f1a',
  muted: '#8a8f8a',
  danger: '#ff6b5e',
}

const STEPS = ['Welcome', 'Preferences', 'Notifications'];
const LANGUAGES = ['TypeScript', 'JavaScript', 'Python'];

export function OnboardingScreen(): JSX.Element {
  const [step, setStep] = useState(0);
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [languages, setLanguages] = useState<string[]>(['TypeScript']);
  const [notify, setNotify] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const progress = useMemo(() => ((step + 1) / STEPS.length) * 100, [step]);

  const toggleLanguage = useCallback((lang: string) => {
    setLanguages(prev => (prev.includes(lang) ? prev.filter(l => l !== lang) : [...prev, lang]));
  }, []);

  const next = useCallback(() => {
    if (step < STEPS.length - 1) setStep(s => s + 1);
  }, [step]);

  const finish = useCallback(async () => {
    setSubmitting(true);
    try {
      await completeOnboarding({ notify, theme, languages });
      setDone(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Onboarding failed.');
    } finally {
      setSubmitting(false);
    }
  }, [notify, theme, languages]);

  if (done) {
    return (
      <SafeAreaView style={styles.safe}>
        <View style={styles.centerContent}>
          <Text style={styles.check}>✓</Text>
          <Text style={styles.title}>You’re all set</Text>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.content}>
        <View style={styles.progressTrack}>
          <View style={[styles.progressFill, { width: `${progress}%` }]} accessibilityLabel={`Step ${step + 1} of ${STEPS.length}`} />
        </View>
        <Text style={styles.title}>{STEPS[step]}</Text>
        {step === 0 && <Text style={styles.body}>Build production-grade React Native apps with one harness.</Text>}
        {step === 1 && (
          <>
            <Text style={styles.sub}>Theme</Text>
            <View style={styles.row}>
              {(['dark', 'light'] as const).map(t => (
                <TouchableOpacity key={t} style={[styles.chip, theme === t && styles.chipActive]} onPress={() => setTheme(t)} accessibilityRole="button">
                  <Text style={styles.chipText}>{t}</Text>
                </TouchableOpacity>
              ))}
            </View>
            <Text style={styles.sub}>Languages</Text>
            <View style={styles.row}>
              {LANGUAGES.map(lang => (
                <TouchableOpacity key={lang} style={[styles.chip, languages.includes(lang) && styles.chipActive]} onPress={() => toggleLanguage(lang)} accessibilityRole="button">
                  <Text style={styles.chipText}>{lang}</Text>
                </TouchableOpacity>
              ))}
            </View>
          </>
        )}
        {step === 2 && (
          <TouchableOpacity style={[styles.toggle, notify && styles.toggleOn]} onPress={() => setNotify(n => !n)} accessibilityRole="switch" accessibilityLabel="Notifications">
            <Text style={styles.toggleText}>{notify ? 'Notifications on' : 'Notifications off'}</Text>
          </TouchableOpacity>
        )}
        {error && <Text style={styles.error}>{error}</Text>}
        {error && <Text style={styles.error}>{error}</Text>}
        <View style={styles.actions}>
          {step > 0 && <TouchableOpacity style={styles.ghost} onPress={() => setStep(s => s - 1)} accessibilityRole="button"><Text style={styles.ghostText}>Back</Text></TouchableOpacity>}
          {step < STEPS.length - 1 ? (
            <>
              <TouchableOpacity style={styles.ghost} onPress={() => setStep(STEPS.length - 1)} accessibilityRole="button"><Text style={styles.ghostText}>Skip</Text></TouchableOpacity>
              <TouchableOpacity style={styles.primary} onPress={next} accessibilityRole="button"><Text style={styles.primaryText}>Next</Text></TouchableOpacity>
            </>
          ) : (
            <TouchableOpacity style={styles.primary} onPress={finish} disabled={submitting} accessibilityRole="button">
              {submitting ? <ActivityIndicator color="{colors.bg}" /> : <Text style={styles.primaryText}>Finish</Text>}
            </TouchableOpacity>
          )}
        </View>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  content: { flex: 1, padding: 24 },
  centerContent: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  check: { fontSize: 48, color: colors.success },
  progressTrack: { height: 4, borderRadius: 2, backgroundColor: colors.border, marginBottom: 24 },
  progressFill: { height: 4, borderRadius: 2, backgroundColor: colors.accent },
  title: { fontSize: 24, fontWeight: '700', color: colors.text, marginBottom: 8 },
  body: { color: colors.textMuted, lineHeight: 22 },
  sub: { color: colors.textMuted, fontSize: 12, marginTop: 16, marginBottom: 8 },
  row: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },
  chip: { backgroundColor: colors.surface, borderRadius: 16, paddingHorizontal: 14, paddingVertical: 8 },
  chipActive: { backgroundColor: colors.accent },
  chipText: { color: colors.textMuted },
  toggle: { backgroundColor: colors.surface, borderRadius: 8, padding: 16 },
  toggleOn: { borderWidth: 2, borderColor: colors.success },
  toggleText: { color: colors.text },
  actions: { flexDirection: 'row', gap: 12, marginTop: 'auto', paddingTop: 24 },
  ghost: { flex: 1, alignItems: 'center', paddingVertical: 14 },
  ghostText: { color: colors.muted },
  primary: { flex: 1, backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 14, alignItems: 'center' },
  primaryText: { color: colors.bg, fontWeight: '700' },
  error: { color: colors.danger, marginTop: 12 },
});
